const c="state",v=[{id:"state-emotion-decisions",title:"Lerner et al. · 2015 · Emotion and decision making · Dossier ST01",url:"https://doi.org/10.1146/annurev-psych-010213-115043",type:"research",finding:"Narrative review of approximately 35 years of research: emotions can influence decisions, including carryover from unrelated situations. Effects may help or harm depending on the emotion and decision.",limitation:"No pooled estimate. Does not validate a three-part state mechanism, universal optimal mood, or one-minute reset."},{id:"state-regulation-meta",title:"Webb, Miles & Sheeran · 2012 · Emotion-regulation strategies · Dossier ST02",url:"https://pubmed.ncbi.nlm.nih.gov/22582737/",type:"research",finding:"Across 306 experimental comparisons, cognitive change averaged d = 0.36, response modulation 0.16, and attentional deployment 0.00. Subcategories and emotional outcomes differed.",limitation:"Mostly experimentally elicited emotion, not treatment populations. Expression and experience differ. Does not validate named question scripts or a universally best strategy."},{id:"state-acute-exercise",title:"Reed & Ones · 2006 · Acute exercise and energetic feelings · Dossier ST03",url:"https://experts.umn.edu/en/publications/the-effect-of-acute-aerobic-exercise-on-positive-activated-affect/",type:"research",finding:"158 studies, 450 effects, 13,101 participants: average corrected exercise-associated change in energetic positive feelings was 0.47. Control-condition change was separately reported as -0.17.",limitation:"These separately reported changes are not a randomized treatment contrast. Mostly healthy volunteers with heterogeneous responses. No proven two-minute dose or depression treatment."},{id:"state-exercise-mental-health",title:"Singh et al. · 2023 · Physical activity and distress · Dossier ST04",url:"https://doi.org/10.1136/bjsports-2022-106195",type:"research",finding:"97 reviews covering 1,039 unique randomized trials and more than 128,119 participants found average symptom reductions. Median depression and anxiety effects were -0.43 and -0.42.",limitation:"77 reviews were critically low quality. Longer programs differ from brief movement. Distress -0.60 came from one review of six trials with 508 participants; another small trial was nonsignificant."},{id:"state-facial-feedback",title:"Coles, Larsen & Lench · 2019 · Facial feedback · Dossier ST05",url:"https://doi.org/10.1037/bul0000194",type:"research",finding:"138 studies and 286 effects: overall d = 0.20, 95% CI 0.14 to 0.26, combining emotional experience and affective judgments. Effects were small and variable.",limitation:"Published count is 138, not 136. Some judgment effects showed publication-bias signals. Does not establish smiling as a reliable distress treatment."},{id:"state-cyclic-sighing",title:"Balban et al. · 2023 · Brief respiration practices · Dossier ST09",url:"https://doi.org/10.1016/j.xcrm.2022.100895",type:"research",finding:"108 randomized adults, mostly recruited from a Stanford undergraduate psychology class, practiced five minutes daily for 28 days. Modeling favored breathing for positive affect.",limitation:"Exploratory, retrospectively registered trial. Does not establish anxiety superiority, a two-breath dose, durability, or treatment efficacy."},{id:"state-affect-labeling",title:"Lieberman et al. · 2007 · Affect labeling · Dossier ST11",url:"https://doi.org/10.1111/j.1467-9280.2007.01916.x",type:"research",finding:"30 healthy adults labeled emotions on faces during brain imaging. Emotion-word versus gender-name labeling differed on an amygdala measure, with reported d = 0.79.",limitation:"Not a subjective distress-recovery outcome. Does not establish benefits of milder vocabulary, self-labeling, lasting symptom relief, or this worksheet."},{id:"state-gratitude-expressed",title:"Kirca, Malouff & Meynadier · 2023 · Expressed gratitude · Dossier ST13",url:"https://doi.org/10.1007/s41042-023-00086-6",type:"research",finding:"23 studies and 25 randomized samples: positive wellbeing g = 0.22 against neutral controls. Against bona fide activities, g = 0.12 with a confidence interval including zero.",limitation:"Article participant totals conflict, so no exact N is taught. Does not validate a morning priming package, future-scene imagery, or superiority to credible alternatives."},{id:"state-positive-self-statements",title:"Wood et al. · 2009 · Positive self-statements · Dossier ST12",url:"https://doi.org/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Early university-sample experiments suggested different responses to repeated positive statements depending on self-esteem, including possible poorer responses for some participants.",limitation:"Later replication attempts did not reproduce mood, state-esteem, or moderation findings. Neither universal benefit nor universal harm is established. No evidence of incantation superiority."},{id:"state-mental-contrasting",title:"Wang, Wang & Gai · 2021 · Goal attainment · Dossier ST15",url:"https://doi.org/10.3389/fpsyg.2021.565202",type:"research",finding:"21 articles, 24 independent effects, 15,907 participants: mental contrasting with response planning showed g = 0.336, with a smaller publication-bias-adjusted estimate of 0.242.",limitation:"Heterogeneous studies and possible publication bias. Does not validate Dickens imagery, shame, rigid must language, or causal delivery-format superiority."},{id:"state-self-compassion-motivation",title:"Breines & Chen · 2012 · Improvement motivation · Dossier ST16",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Four short experiments supported compatibility of compassion and improvement motivation. After test failure, study time averaged 306.5 seconds versus 203.2 with no reminder.",limitation:"Second-test scores did not significantly differ; the self-esteem comparison was inconclusive. Does not prove sustained change, actual repair, or Dickens efficacy."},{id:"state-nhs-panic",title:"NHS · Panic disorder · Dossier ST18",url:"https://www.nhs.uk/mental-health/conditions/panic-disorder/",type:"guidance",finding:"Recurrent unexpected panic warrants professional assessment. Established treatment options include cognitive behavioral therapy and medication.",limitation:"Guidance, not a coaching-effect study. ODA cannot diagnose panic or assume new chest pain, fainting, or unexplained breathing difficulty is harmless anxiety. Use appropriate medical or emergency help."},{id:"state-affirmation-replication",title:"Flynn & Bordieri · 2020 · Affirmation replication · Dossier ST20",url:"https://doi.org/10.1016/j.jcbs.2020.03.003",type:"research",finding:"Two university analogue experiments failed to reproduce earlier mood, state-esteem, or trait-esteem moderation findings for positive affirmations.",limitation:"Null results do not establish equivalence or settle every statement. Two failed replication attempts leave the earlier benefits and self-esteem differences uncertain."}];function a(e){const t=e.suggestions;return{schemaVersion:2,revision:2,id:e.id,courseId:c,locale:"en",title:e.title,goal:e.goal,minutes:{learning:6,suggestedAction:t.minutes[0],review:2},direction:{hook:e.hook,reason:{id:`${e.id}-reason`,label:e.reason,kind:"text",maxLength:160,optional:!0,suggestions:e.reasons},why:{id:`${e.id}-why`,label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:`${e.id}-cost`,label:"What does the current pattern cost you?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:e.paragraphs,example:e.example},move:{invitation:e.invitation,instructions:e.instructions,prompts:[],suggestions:t,suggested:{action:t.action[0],minimum:t.minimum[0],minutes:t.minutes[0],cueHint:t.cue[0],placeHint:t.place[0],obstacleHint:e.obstacle,fallbackHint:t.fallback[0],observationHint:t.observation[0]},stopRule:e.stop,accessibleAlternative:e.accessible},result:{question:e.result,observationPrompt:e.observation},judgment:{primary:e.scenario},carry:{takeaway:e.takeaway,followUp:{questionId:`${e.id}-return`,question:e.follow,observationPrompt:e.followObservation,adjustmentPrompt:"What would make the next attempt fit your life?"}},goDeeper:{sections:e.depth,sourceIds:e.sources}}}const n=[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],d=a({id:"state-1",title:"Do not let one argument write the next",goal:"Notice carried-over emotion, then make one useful request in a safe setting.",hook:"Still angry about the last conversation? Give your next request its own chance.",reason:"What is carryover costing this next conversation?",reasons:["Ask clearly at home","Protect a working relationship","Stop carrying one argument forward"],paragraphs:["A feeling can arrive before the situation it seems to explain. Irritation from a difficult shift may color a repair request at home. Research shows that emotions can carry into unrelated decisions. That does not make the feeling wrong. It asks you to check what it belongs to.","Choose one recurring transition for this course: before a call, a message, or a task you care about. Name the feeling and its likely source. Then make one useful move without demanding calm first. Keep anger that signals real harm in view. A clear request, protection, or support may matter more than changing your mood."],example:{title:"Dana's repair request",text:"At 6 p.m., Dana comes home irritated after a tense shift. A leaking tap needs attention. She notices that her landlord has not caused the argument at work. Seated at the kitchen table, she sends a clear repair request. The reply asks for a photo. She records the request and sends it, still irritated."},invitation:"Pick one useful request at your chosen transition. Notice the feeling, then use your sentence.",instructions:["Name where the feeling may have started.","Make one clear request in a safe setting."],suggestions:{action:["Send one clear repair request","Ask for one needed clarification","Make one practical support request"],minimum:["Send one request sentence","Ask one specific question","Name one support need"],when:n,cue:["Before my next necessary message","At my next safe check-in"],place:["Seated at my kitchen table","In a safe message thread"],minutes:[2,1,5],fallback:["Use a safe written message","Choose a later safe opening"],observation:["My request and the actual reply","Whether I made the request"]},obstacle:"The previous conversation is still on my mind",stop:"If there is real danger, pause and seek protection or support.",accessible:"Keep eyes open. Stay seated, notice the room, and use your usual communication method.",result:"Did you make your chosen request?",observation:"What did you request, and what reply came back?",scenario:{id:"state-1-carryover-request",scenario:"A repair-booking window closes in two minutes. After a tense shift, Dana wants a leak fixed this week. Her landlord has responded reasonably before.",question:"What gives this request a fair start?",bestOptionId:"name-and-request",options:[{id:"pause-then-request",text:"Take a five-minute pause to collect her thoughts, then send the factual request with a repair-date question.",feedback:"A defined pause can help organize a request. Here it misses the booking window, although the message is manageable now. Dana can send a factual date request while irritation remains."},{id:"describe-without-date",text:"Send a concise description of the leak now and let the landlord suggest what happens next.",feedback:"This reports the problem accurately and reaches the open window. It leaves timing unspecified, though Dana needs a repair this week. Asking for a date makes that need visible without demanding agreement."},{id:"name-and-request",text:"Notice the carried-over irritation, describe the leak, and ask clearly for a repair date.",feedback:"This separates the feeling from the evidence about this conversation. Dana makes the needed request and can record the reply. Calm and agreement are not required results."}]},takeaway:"Check where the feeling came from. Let the next request answer its own facts.",follow:"Did noticing carryover change your request, even if your mood stayed the same?",followObservation:"What changed in the request or mood? Unchanged is a valid answer for either.",depth:[{heading:"Emotions can travel between decisions",paragraphs:["Lerner and colleagues reviewed roughly 35 years of research on emotion and decision making. Their account describes incidental emotions: feelings that begin elsewhere and influence a new judgment. Emotions can help as well as hinder decisions. The useful question is whether this feeling supplies information about the present situation or reflects something that happened before it. [ST01: state-emotion-decisions]","That distinction does not ask you to dismiss anger, sadness, or worry. A repeated insult, an unresolved need, and a tiring shift are different facts. Name the current evidence before choosing your response. If you need a repair, ask for a repair. If you need protection, choose protection. This lesson uses an ordinary request to make that decision visible. It does not establish that naming the carryover changes emotion, guarantees cooperation, or solves an unsafe relationship."]},{heading:"A continuing experiment, not a mood test",paragraphs:["For this course, keep one recurring transition and one life direction. Later lessons offer a tool only when your records suggest a problem it could address. You are not collecting seven obligations. The meaningful observation is what you actually requested, started, changed, or stopped at that transition. An unchanged mood and an unanswered message can coexist with a completed request.","Webb and colleagues combined 306 experimental comparisons of emotion-regulation strategies. Changing an interpretation showed average benefits, but the strategies and outcomes varied. Some outcomes concerned expression, others experience. Hiding a feeling is not evidence that it disappeared. These laboratory comparisons do not validate a body, focus, and language triad or this short ODA exercise. [ST02: state-regulation-meta] Keep the record small and factual, then choose your next attempt from the response and your circumstances."]}],sources:["state-emotion-decisions","state-regulation-meta"]}),l=a({id:"state-2",title:"Still flat? Give the real task a chance",goal:"Test one comfortable preparation at your existing transition, then do one useful part of the task.",hook:"You moved, but the energy lift never came. Can the next small task still happen?",reason:"What useful task waits, and when would recovery serve you better?",reasons:["Start within my capacity","Make progress on my work","Leave room for recovery"],paragraphs:["A bout of aerobic exercise can increase energetic feelings on average. That differs from activity-program research on clinical symptoms. Neither establishes two minutes as a reliable mood-changing dose.","Keep your existing transition and useful task. If movement fits your capacity, test one comfortable option with music and posture unchanged. Then try the task minimum if appropriate. Rest or a nonmovement cue may fit better. Record the preparation and your actual useful task separately; doing one does not prove the other happened."],example:{title:"Marcus's first slide",text:"At 9 a.m., Marcus feels flat before drafting a briefing. He chooses a short comfortable walk, leaving his playlist off. Back at his desk, his energy feels unchanged. He writes one usable slide sentence anyway. He records both facts. The slide still needs work, and he chooses a seated start for the next trial."},invitation:"At the same transition, try one comfortable preparation if useful. Then do your task minimum.",instructions:["Choose one tool, or keep ordinary nonmovement preparation.","Do one useful task step within your capacity."],suggestions:{action:["Write one usable task sentence","Complete one small work correction","Send my chosen clear request"],minimum:["Write one usable sentence","Correct one actual item","Send one request sentence"],when:n,cue:["After optional comfortable movement","At my existing task transition"],place:["Seated at my work surface","In my accessible work space"],minutes:[2,1,5],fallback:["Use a seated nonmovement start","Rest and choose another opportunity"],observation:["The preparation and task actually done","Whether movement caused discomfort"]},obstacle:"Energy stays low after the preparation",stop:"Stop movement if uncomfortable. Choose rest or support when needed.",accessible:"Use seated movement, eyes-open attention to the room, or a nonmovement cue. No smile required.",result:"Did you do the useful task minimum?",observation:"What preparation and task step actually happened?",scenario:{id:"state-2-unchanged-energy",scenario:"After a comfortable walk, Marcus feels unchanged energy without discomfort. His slide facts are checked, and one sentence is manageable. He has three minutes left.",question:"Which next move makes the experiment useful?",bestOptionId:"task-and-record",options:[{id:"timed-seated-start",text:"Spend two minutes settling into a seated start, then write the slide sentence during the remaining minute.",feedback:"A seated start can be useful when movement causes discomfort or access requires it. Marcus reports neither here. Extra preparation consumes most of the available time without addressing an identified obstacle."},{id:"task-and-record",text:"Write the usable sentence, record unchanged energy, and consider another comfortable preparation at the next trial.",feedback:"The task can happen without the promised feeling change. Marcus learns what preparation he tried and whether he started. He can adjust later without increasing effort to force a mood lift."},{id:"check-and-draft",text:"Ask a colleague to confirm the checked slide fact, then draft a provisional sentence while awaiting their reply.",feedback:"A provisional draft and second check can resolve genuine factual uncertainty. The facts are already checked here. That adds a reply dependency where one usable sentence can be written and recorded now."}]},takeaway:"Test the preparation honestly. Judge the useful task by what you actually did.",follow:"Did the preparation help you start, cause discomfort, or point toward rest?",followObservation:"Describe help, discomfort, a recovery need, or no clear difference separately from the task outcome.",depth:[{heading:"Short-term energy and treatment are different questions",paragraphs:["Reed and Ones synthesized 158 studies involving 13,101 participants and single aerobic-exercise bouts. The review reported an average exercise-associated change of 0.47 in positive activated affect, meaning feelings such as energy and alertness. The control-condition change was reported separately. These are not a 0.47 randomized exercise-versus-control treatment effect. Individual responses and study procedures varied. [ST03: state-acute-exercise]","That result does not prove a two-minute dose, reliable energy for everyone, or treatment of depression. A separate overview of longer physical-activity programs found average symptom reductions, with many underlying reviews rated critically low quality. [ST04: state-exercise-mental-health] Your brief preparation is an optional personal trial. Match it to access, health, and capacity. If the record points toward fatigue or discomfort, changing the tool, asking for support, or protecting recovery can serve your direction better than extending the exercise."]},{heading:"Optional additions do not need to become requirements",paragraphs:["You do not need a smile, an expansive pose, or a particular song to start your task. Coles and colleagues reviewed 138 studies and 286 effects. The overall facial-feedback estimate was small, at 0.20, combining emotional experience and judgments. Effects varied, and some judgments showed publication-bias signals. This does not establish smiling as a reliable distress response. [ST05: state-facial-feedback] No forced smile belongs in your preparation.","For this continuing experiment, change one preparation at a time and keep the useful task recognizable. Leave your other conditions ordinary rather than adding a song, pose, and movement together and then guessing which worked. A personal observation can help you choose another trial; it cannot isolate a biological mechanism or establish causality. If the next task still fits your capacity, its minimum can happen without an energy lift. If recovery fits better, record that choice honestly instead of demanding a brighter feeling."]}],sources:["state-acute-exercise","state-exercise-mental-health","state-facial-feedback"]}),h=a({id:"state-3",title:"Too wound up? Pause without chasing calm",goal:"Choose a comfortable pause, then make your existing useful response or an appropriate support step.",hook:"Another breathing drill can wait. What reply needs room for a deliberate choice?",reason:"What would a pause support or delay?",reasons:["Reply more deliberately","Respect a stop signal","Ask for useful support"],paragraphs:["The widely reported sighing study used five minutes daily for 28 days. It did not test two breaths as an instant calm button. A gentle breathing pause is optional preparation, not the action your chosen direction needs.","Return to the same transition and response. Stay seated in a safe place. You may keep ordinary breathing and eyes open, noticing the room instead. If comfortable, try one gentle inhale, a small second inhale, and an unforced slow exhale. Stop for dizziness, tingling, breathlessness, or discomfort. Then choose the reply, rest, or support that fits. New severe physical symptoms need medical assessment, not a stress explanation."],example:{title:"Leah's delayed reply",text:"At her desk after lunch, Leah is tense about a nonurgent email. Breath focus feels uncomfortable, so she keeps her eyes open and notices the window frame. She then sends one factual clarification. Her worry remains, and the answer has not arrived. She records the outward pause and the sentence, without claiming a breathing success."},invitation:"Choose a comfortable pause before your same response. Ordinary breathing and looking outward are valid.",instructions:["Stay seated, away from driving, water, and fall risks.","After the pause, do your response minimum if appropriate."],suggestions:{action:["Send one deliberate reply sentence","Ask for one needed clarification","Make one support request"],minimum:["Send one factual sentence","Ask one clear question","Name one support need"],when:n,cue:["After an optional comfortable pause","Before my next nonurgent reply"],place:["Safely seated at my desk","In a safe private chair"],minutes:[2,1,5],fallback:["Look outward with ordinary breathing","Stop and choose a support step"],observation:["Comfort and the response actually made","Whether I respected a stop signal"]},obstacle:"Breath focus feels uncomfortable",stop:"Stop for dizziness, tingling, breathlessness, or discomfort. Resume ordinary breathing. New severe chest pain or unexplained breathing difficulty needs medical assessment.",accessible:"Keep eyes open, stay seated, look at a neutral object, and skip altered breathing.",result:"Did you make your chosen response?",observation:"What felt comfortable, and what response did you actually make?",scenario:{id:"state-3-uncomfortable-pause",scenario:"Leah stops a breathing trial and resumes ordinary breathing while seated. Light-headedness remains and is unfamiliar. Her reply is nonurgent; a colleague nearby can help.",question:"What should change now?",bestOptionId:"stop-and-support",options:[{id:"stop-and-support",text:"Stay seated with ordinary breathing, postpone the email, and ask her colleague for help obtaining medical advice.",feedback:"She has stopped appropriately. The symptom remains and is unfamiliar, so timely help takes priority over the email or another tool. Severe symptoms or immediate danger require emergency help."},{id:"stop-and-look-outward",text:"Stay seated with ordinary breathing, use the window frame as an outward anchor, then reassess before replying.",feedback:"Outward attention can replace uncomfortable breath focus. Here the unfamiliar symptom persists after stopping, so an anchor alone should not delay asking for help and appropriate medical advice."},{id:"stop-and-defer",text:"Stay seated with ordinary breathing, postpone the email until tomorrow, and check later whether the light-headedness has gone.",feedback:"Postponing a nonurgent message protects time for care. But delaying the message does not address a persistent unfamiliar symptom. Ask for appropriate help now rather than postponing that assessment too."}]},takeaway:"A safe stop is useful information. Calm is not a condition for a thoughtful response.",follow:"Was the pause comfortable, and did it support the response or call for another tool?",followObservation:"Describe comfort, any stop or support need, and the later response separately.",depth:[{heading:"What the sighing trial actually tested",paragraphs:["Balban and colleagues randomized 108 adults to brief breathing practices or mindfulness. Participants practiced for five minutes a day across 28 days. Most were recruited from a Stanford undergraduate psychology class. The study was exploratory and retrospectively registered. The modeling favored breathing for positive affect; it did not establish superiority for anxiety or a reliable result from two breaths. [ST09: state-cyclic-sighing]","The studied cyclic-sighing procedure used a slow inhale, a shorter second inhale, and a slow exhale while seated or lying down. This lesson offers a comfortable optional trial and ordinary-breathing alternatives. Those safety and access choices are ODA adaptations. Do not fill or empty your lungs to strain, hold your breath, or accelerate to force an effect. Your record can distinguish preparation, a stopped trial, and the actual reply. One does not stand in for the others."]},{heading:"Breathing does not diagnose a symptom",paragraphs:["A breathing exercise cannot tell you why a physical symptom occurred. NHS guidance recommends professional assessment for recurrent unexpected panic and describes established treatment options. The boundary for this course is straightforward: ODA is education, not diagnosis or treatment. Do not assume unfamiliar chest pain, fainting, or unexplained breathing difficulty is harmless anxiety. New severe symptoms require medical assessment; immediate danger requires emergency help. [ST18: state-nhs-panic]","You can choose a practical response without altered breathing. Keep eyes open, notice a neutral object, stay seated, or ask for support. If a pause leaves you more uncomfortable, drop it rather than calling persistence progress. There is no requirement to obtain calm before making a useful request when the setting is safe and the response is manageable. There is also no requirement to continue the request when rest, protection, or human help is the appropriate next step."]}],sources:["state-cyclic-sighing","state-nhs-panic"]}),u=a({id:"state-4",title:"Another replay? Make the question earn its place",goal:"Turn one question about your recurring situation into a useful action or an appropriate support request.",hook:"When another why adds no new information, what answer would change your next ten minutes?",reason:"What does another replay postpone in this situation?",reasons:["Clarify a real problem","Use what I learned","Stop postponing a useful request"],paragraphs:["A question is useful when its answer changes a choice. Asking why can reveal a cause, a skill gap, or who owes repair. It is not automatically harmful. Another replay without new information may leave your next move untouched.","At your existing transition, ask what needs clarification, change, or support. Give the answer a verb: send, correct, ask, rest. Research compares broad strategies, not this script. Treat it as a practical aid, use the answer if feasible, then record the behavior rather than its encouraging sound."],example:{title:"Omar's missing approver",text:"At 2 p.m., Omar reviews a stalled project request at his desk. Asking why reveals a missing budget approver, not a personal failure. He finds the named contact in the project notes and sends one clarification. No answer arrives that afternoon. He records the question, the message, and the unresolved approval instead of writing more encouraging prompts."},invitation:"Ask one useful question about the same situation. Do the smallest appropriate action its answer suggests.",instructions:["Keep investigation and accountability when they matter.","Turn the answer into one actual request or correction."],suggestions:{action:["Send one needed clarification","Correct one identified task problem","Ask for one missing resource"],minimum:["Send one clarification sentence","Fix one actual item","Name one missing resource"],when:n,cue:["After answering my useful question","At my existing task transition"],place:["At my desk or phone","In a safe message thread"],minutes:[2,1,5],fallback:["Ask for help locating the answer","Schedule a suitable response opportunity"],observation:["The answer and action actually taken","What remains unresolved"]},obstacle:"I keep analyzing without a next move",stop:"Do not replace needed protection or support with another reflection exercise.",accessible:"Answer silently or through your usual communication method. A support request can be the useful action.",result:"Did you act on the useful answer?",observation:"What did the question reveal, and what did you do?",scenario:{id:"state-4-question-to-action",scenario:"Omar confirms that his request has the required budget fields but never reached the approver. The listed approver accepts clarification messages now.",question:"What completes the useful question?",bestOptionId:"contact-approver",options:[{id:"check-budget-field",text:"Check the submitted budget fields once more before sending the clarification, so the approver gets a complete request.",feedback:"Checking required fields can prevent a wasted message. Omar has already confirmed them, and the missing step is delivery. Repeating the check adds preparation without resolving that known gap."},{id:"break-then-contact",text:"Take a five-minute break, then send the clarification while keeping frustration separate from the factual message.",feedback:"This has an endpoint and can help when a break is needed. No such need is identified here. The factual clarification is ready and addresses the missing approval directly."},{id:"contact-approver",text:"Send the listed approver a factual clarification, then record the response or the absence of one.",feedback:"This turns the identified cause into a controllable action. The reply may not arrive, and approval remains external. Omar can still record whether he made the useful request."}]},takeaway:"An answer earns its place when it changes a useful next move.",follow:"Did your question clarify something and change your action, or only sound encouraging?",followObservation:"Name what became clearer and what changed; no new information or change is valid.",depth:[{heading:"Attention findings do not validate a question set",paragraphs:["Webb and colleagues synthesized 306 experimental comparisons. Broad cognitive-change strategies showed an average effect of 0.36 on emotional outcomes. Attentional deployment averaged near zero overall, while its subcategories differed. These categories covered varied instructions and short experimentally elicited emotions. They do not prove that any named morning questions improve your state, or that asking why and concentrating on a problem are generally harmful. [ST02: state-regulation-meta]","Use the distinction to check the job of a question. Investigation can establish facts. Accountability can identify a responsible person. Planning can name a missing resource. Each may deserve time. If your answer identifies a feasible behavior, choose that behavior. If it identifies an external constraint, do not recast the constraint as an attitude problem. This ODA question-and-action pairing is an adaptation, not a tested protocol with a verified dose or promised emotional result."]},{heading:"Keep the answer connected to your experiment",paragraphs:["Your experiment already has a direction, transition, and useful response. Keep those visible. The question should improve the response rather than become a new daily ritual. For example, a clarification request can target the missing approver; a work step can target the mistaken item; a protection step can target a harmful interaction. Ask only for information relevant to the next choice.","Emotions may influence the way you interpret an answer, and they can carry over from another event. Lerner and colleagues describe both helpful and harmful effects of emotion on decisions. [ST01: state-emotion-decisions] Record the evidence you gained and the action you actually took. A useful answer may still leave the larger problem unresolved. If nothing could be acted on safely, record that constraint or choose support. Do not turn a thoughtful pause into failure, or a written question into proof of the downstream action."]}],sources:["state-regulation-meta","state-emotion-decisions"]}),p=a({id:"state-5",title:"The message hurt. Do not rewrite the facts",goal:"Separate a fact from a guessed motive, then clarify or protect yourself in the same recurring situation.",hook:"That message hurt. Before guessing their motive, check the words and choose a safe response.",reason:"What would a safer response protect or cost?",reasons:["Use feedback without self-attack","Stop accepting unfair treatment","Ask before guessing a motive"],paragraphs:["An event and an explanation differ. “The message contains an insult” is checkable evidence. “They want to ruin my career” guesses a motive. An alternative explanation must fit the facts, without calling harm harmless.","At your same transition, name one fact and what you still do not know. Then clarify, correct, set a boundary, or seek support. Milder emotion words are not automatically truer. The classic labeling study measured brain responses to faces, not relief from renaming distress. Choose accuracy over positivity."],example:{title:"Nina's documented messages",text:"At 4 p.m., Nina receives another insulting team message. In a private chair, she separates the saved words from her guess about the sender's motive. She stays angry. Instead of calling it a misunderstanding, she asks a trusted manager about a safe reporting route. The manager needs time to check. Nina records the request and protects the messages."},invitation:"Use one fact to improve your existing response. Clarify uncertainty, or choose protection when harm is documented.",instructions:["Separate observable facts from guessed motives.","Make one appropriate clarification, correction, boundary, or support request."],suggestions:{action:["Ask about a safe support route","Send one factual clarification","Correct one confirmed work error"],minimum:["Make one support request","Ask one factual question","Correct one actual item"],when:n,cue:["After checking an upsetting message","Before my next planned reply"],place:["In a safe private chair","In a trusted support channel"],minutes:[2,1,5],fallback:["Keep evidence and seek safer support","Choose another safe response opportunity"],observation:["The fact and response actually used","What evidence changed my interpretation"]},obstacle:"A positive explanation would hide real harm",stop:"Do not reframe abuse or danger as a misunderstanding. Choose protection and support.",accessible:"Name facts silently, type, sign, or ask for assistance. No body focus or milder label is required.",result:"Did you make the factual response you chose?",observation:"What evidence did you use, and what response happened?",scenario:{id:"state-5-documented-insults",scenario:"Nina has secured messages containing repeated insults. A trusted manager is available now; a reporting portal opens tomorrow. There is no immediate danger or known motive.",question:"Which next step uses the facts and available support?",bestOptionId:"facts-and-support",options:[{id:"copy-and-wait",text:"Create another protected copy of the saved insults, then wait for the reporting portal to open tomorrow.",feedback:"Preserving evidence serves protection. These messages are already secured, though, so another copy adds no identified safeguard. The available manager can clarify a safe route now without requiring contact with the sender."},{id:"facts-and-support",text:"Separate the documented insults from guessed motives, then ask a trusted person about a safe support route.",feedback:"This preserves uncertainty about motive while recognizing actual harm. Nina can seek protection without proving a hidden intention, changing her emotion label, or confronting the sender directly."},{id:"wait-safe-portal",text:"Avoid contacting the sender, wait for tomorrow's reporting portal, and use the saved messages to ask about support.",feedback:"Avoiding direct contact and using a reporting channel can be protective. Here trusted support is available sooner. Asking about the route now preserves her options; it does not force reporting or confrontation."}]},takeaway:"Change the interpretation only as far as the evidence allows. Then make the appropriate response.",follow:"What evidence supported or challenged your interpretation, and did your response fit it?",followObservation:"Name the relevant fact, remaining uncertainty, and whether your response fit the evidence.",depth:[{heading:"A brain measure is not a distress treatment",paragraphs:["Lieberman and colleagues studied 30 healthy adults labeling emotions on faces during brain imaging. The emotion-word condition differed from the gender-name condition in an amygdala measure. The study did not show that replacing furious with annoyed reduces real-life distress, that self-labeling has the same effect, or that a benefit lasts. [ST11: state-affect-labeling] Those are different interventions and outcomes.","This lesson uses a fact, feeling, and uncertainty check as an ODA aid. Its value here is to make the next choice explicit. You can use an accurate strong feeling word, choose no label, or keep the note private. A documented insult remains an insult even if you feel less angry later. A brief delayed reply may remain ambiguous even if you feel very anxious now. Use what can be checked, preserve what is unknown, and choose the response that fits your safety and direction."]},{heading:"Reappraisal can include a boundary",paragraphs:["Changing an interpretation is often called reappraisal. Webb and colleagues found average benefits across varied experimental comparisons, with clear differences between strategies and outcomes. That does not make a positive explanation universally best. The evidence does not validate the exact one-minute worksheet, and it does not justify ignoring feedback, material constraints, or harm. [ST02: state-regulation-meta]","A fair interpretation can make responsibility more specific: I missed this item, so I will correct it. It can also reduce unsupported blame: I do not know why the reply is late, so I will ask. Where harm is documented, it can support protection: I do not need to prove a motive before seeking help. Carry the same chosen experiment forward by recording which response happened and what new evidence emerged. An unanswered request stays unanswered. A safe stop stays a stop. Neither requires a more optimistic story to make the record acceptable."]}],sources:["state-affect-labeling","state-regulation-meta"]}),m=a({id:"state-6",title:"Positive words feel fake? Make one useful move",goal:"Use a credible action sentence to start your existing task without requiring gratitude or a mood change.",hook:"Your morning routine is ready. Has it bought you a real action yet?",reason:"What does extending the routine keep postponing?",reasons:["Start the action I chose","Use words I can believe","Keep preparation short"],paragraphs:["Sweeping positive statements are not a proven way to improve everyone's mood. Early benefit and backfire findings failed later replication. There is no verified evidence here that forceful delivery or incantations solve this. Choose a plain instruction you can act on.","At your same transition, try “I can send one clear request while unsure,” then send it if suitable. Optional gratitude should describe something real, not an imagined achievement. Skip it if forced. The sentence is preparation. Record the behavior separately; no convincing feeling or complete ritual is needed."],example:{title:"Aisha's first request",text:"After her first drink at 8 a.m., Aisha has two minutes before leaving. “I am unstoppable” feels false. She chooses “I can ask one clear question while unsure” and sends the request she has been delaying. She skips gratitude today. There is no reply before she leaves. She records the sent sentence, without calling uncertainty a failure."},invitation:"Keep the routine short. Use one credible sentence, then do your existing useful action.",instructions:["Choose a statement about controllable behavior.","Try the action now if suitable, or save its real cue."],suggestions:{action:["Send my chosen clear request","Write one usable task sentence","Make one practical support request"],minimum:["Send one clear sentence","Write one usable sentence","Name one support need"],when:n,cue:["After my first drink","At my existing task transition"],place:["Seated at my kitchen table","In my usual task space"],minutes:[2,1,5],fallback:["Skip the ritual and use my sentence","Choose the next realistic opening"],observation:["Whether words led to the action","What preparation delayed the action"]},obstacle:"I keep extending the preparation",stop:"Skip gratitude, imagery, or statements that increase distress. Choose ordinary support instead.",accessible:"Use ordinary breathing and eyes-open attention. Say, type, sign, or silently use the instruction.",result:"Did you do the action after your sentence?",observation:"What did you actually start, send, or change?",scenario:{id:"state-6-believable-start",scenario:"Aisha has two minutes before leaving. Her checked question is clear, courteous, and ready through a safe channel. She keeps delaying because she wants to sound confident.",question:"Which version fits this morning?",bestOptionId:"credible-and-send",options:[{id:"rehearse-and-send",text:"Rehearse the message aloud for ninety seconds, then send the checked question before leaving.",feedback:"Timed rehearsal can help an unclear or unfamiliar request. This question is already clear and checked. Rehearsing consumes most of her opening without addressing the belief that confidence must come first."},{id:"credible-and-send",text:"Use a credible instruction about asking while unsure, then send the ready question through the safe channel.",feedback:"This pairs controllable words with an available act. Aisha does not have to believe a sweeping claim, feel grateful, or lose uncertainty before making her useful request."},{id:"polish-and-send",text:"Draft a brief opening and closing for the message, then send the ready question before she leaves.",feedback:"An opening and closing can add courtesy where needed. Her ready question already communicates the request. More polishing leaves less time to send; a credible instruction addresses starting while unsure directly."}]},takeaway:"Make the words believable enough to use. Let the action supply the evidence.",follow:"Did the sentence help you act, delay the move, or make no clear difference?",followObservation:"Describe help or delay separately from the action outcome; no clear difference is valid.",depth:[{heading:"Affirmation evidence is mixed",paragraphs:["Wood and colleagues studied repeated positive self-statements in university samples. Their early findings suggested different responses depending on self-esteem, including a poorer response among some participants. Two later replication attempts by Flynn and Bordieri did not reproduce the mood, state-esteem, or moderation findings. The correct boundary is mixed evidence, not a claim that affirmations help everyone or harm everyone. [ST12: state-positive-self-statements; ST20: state-affirmation-replication]","The evidence does not establish embodied incantations as a solution. A credible instruction about one behavior is offered here as practical coaching, not a proven psychological treatment. You may use your own words, skip the statement, or choose support. Keep the task and its minimum clear enough to observe. Speaking a sentence about a future act is preparation. Sending the request, correcting the item, or asking for support is the act you can later report."]},{heading:"Appreciation has limits and no obligation",paragraphs:["Kirca and colleagues reviewed 23 studies with 25 randomized samples of expressed gratitude. Positive wellbeing showed a small average benefit against neutral controls, with an effect of 0.22. Against bona fide wellbeing activities the estimate was smaller and statistically inconclusive. [ST13: state-gratitude-expressed] That means the comparison activity matters when judging the apparent benefit.","That research does not establish a ten-minute priming package, three imagined future scenes, an optimal morning sequence, or superiority to appropriate clinical treatment. If you choose appreciation, use a real detail you welcome. Do not require a silver lining in loss or gratitude toward someone unsafe. A hoped-for future is a possibility, not a memory or an accomplished result. The practical test for your continuing experiment is whether the optional preparation supported the same useful action. Drop it if it adds delay or discomfort."]}],sources:["state-positive-self-statements","state-affirmation-replication","state-gratitude-expressed"]}),f=a({id:"state-7",title:"Stop collecting resets. Choose what earns another week",goal:"Use your actual records to keep, shrink, replace, or pause the same experiment for next week.",hook:"The routine keeps growing while the task waits. Which part helped you start, and which added delay?",reason:"What would keeping this experiment displace next week?",reasons:["Keep the useful next move","Protect needed recovery","Drop a ritual that delays me"],paragraphs:["A desired future paired with an obstacle and response plan has more direct evidence than catastrophic-cost imagery. Imagined costs are predictions, not facts. Shame and stronger vows are not required.","Review actual records at your same transition. Which preparation supported the useful response? Which caused discomfort, delay, or no clear difference? Keep one helpful version, change one problem, or pause. Make next week's minimum fit your capacity, and try an appropriate step if feasible. Rest, protection, and support can belong in the plan."],example:{title:"Evan's smaller standard",text:"On Sunday afternoon, Evan reviews his portfolio-start records at his desk. One outward pause helped him start; a long ritual delayed him twice. After poor sleep today, he skips the ritual and corrects one caption. He schedules the same small step for Tuesday. The portfolio is unfinished, but his next plan now fits the evidence."},invitation:"Use the records from your same experiment. Keep one useful version and try its feasible minimum.",instructions:["Review reported attempts; leave missing outcomes unknown.","Keep, shrink, change, or pause one version for next week."],suggestions:{action:["Repeat my useful task step","Make my next clear request","Carry out my chosen recovery step"],minimum:["Correct one useful task item","Use one request sentence","Take the recovery time I chose"],when:n,cue:["At my tested useful transition","At my next realistic opening"],place:["In my usual task space","In my chosen recovery space"],minutes:[2,1,5],fallback:["Shrink the step to fit capacity","Pause and choose a support step"],observation:["What I repeated or changed","Which obstacle actually occurred"]},obstacle:"My usual plan asks more than my capacity allows",stop:"Skip distressing cost imagery. Rest, protection, and support can be appropriate next moves.",accessible:"Review silently or with assistance. Use an eyes-open, seated, nonmovement option if a pause helps.",result:"Did you do the next minimum you chose?",observation:"What did you keep, change, or pause, and what actually happened?",scenario:{id:"state-7-capacity-review",scenario:"Evan has five usable minutes after poor sleep. His caption has a known error with its correction ready. The deadline is next week; long setup delayed his last two starts.",question:"Which next version fits the evidence?",bestOptionId:"small-caption",options:[{id:"small-caption",text:"Correct one portfolio caption, record the smaller attempt, and choose the next realistic session from his capacity.",feedback:"This preserves the purpose while changing the dose to fit today. Evan can use his records to plan another opportunity without requiring a long ritual or perfect energy."},{id:"sort-next-section",text:"Use the five minutes to sort source notes for the next section, leaving the known caption correction for Tuesday.",feedback:"Sorting notes can prepare a later section, but setup has repeatedly delayed his useful work. The current correction is ready. Completing that small unit tests a version that addresses his recorded obstacle."},{id:"defer-for-checking",text:"Save the caption correction for a rested session tomorrow, using these five minutes to schedule time for checking it.",feedback:"Deferring is appropriate when fatigue makes a task unsuitable or accuracy needs checking. Here the correction is ready and fits his usable capacity. Planning another check postpones an available meaningful unit."}]},takeaway:"Keep the purpose. Let actual attempts and current capacity shape the next version.",follow:"Did your next version fit your capacity, and which obstacle actually affected it?",followObservation:"Name what fit, what got in the way, or why recovery or another change was appropriate.",depth:[{heading:"An obstacle plan has evidence; catastrophe is optional to omit",paragraphs:["Wang and colleagues combined 24 independent effects across 21 articles involving 15,907 participants. Mental contrasting with response planning had a small-to-medium average goal-attainment effect of 0.336. A publication-bias-adjusted estimate was smaller, and study results varied. The procedure combines a feasible desired future, an obstacle, and an if-obstacle-then-response plan. It does not validate a Dickens process, shame induction, or converting every should into a must. [ST15: state-mental-contrasting]","Use an obstacle that your records or circumstances support. If it is internal, name a manageable response. If it is external, resources, a different setting, or help may be needed. An imagined future cost remains a prediction. You do not need to relive painful memories or picture escalating damage to make this plan valid. The shorter record-based approach here is an ODA adaptation, and its duration is an estimate rather than a verified optimal dose."]},{heading:"Consolidate the experiment instead of adding a ritual",paragraphs:["The course began with one transition and one useful response. Review those exact attempts before deciding what deserves another week. Distinguish a preparation tried from a task completed, and an unchanged feeling from a failed minimum. A missing report supplies no outcome. A conditional opening that never occurred can be recorded as no occasion. Let each next choice respond to what is known.","Breines and Chen found that self-compassion could coexist with improvement motivation in short experiments. After test failure, the compassion condition studied longer than a no-reminder condition; second-test performance did not significantly differ, and the self-esteem comparison was inconclusive. [ST16: state-self-compassion-motivation] That supports dropping the assumption that contempt is necessary for effort. It does not guarantee sustained behavior change. Your next version can include support, recovery, or stopping an unsuitable plan. The record and dated return keep those decisions honest, without a compulsory daily streak."]}],sources:["state-mental-contrasting","state-self-compassion-motivation"]}),g=[{id:"state-1",practiceCount:3,correct:2,photo:{id:"1758192139097-1e7f30c2498e",alt:"A man crossing a quiet city street under sunlit trees"}},{id:"state-2",practiceCount:3,correct:1,photo:{id:"1692933216024-8de20c41321a",alt:"A woman walking along a boardwalk through green plants"}},{id:"state-3",practiceCount:3,correct:0,photo:{id:"1763713383838-5cd702c13160",alt:"A woman with her eyes closed, hugging herself gently in a forest"}},{id:"state-4",practiceCount:3,correct:2,photo:{id:"1543379232-77ee894c85dd",alt:"A woman in a knit hat facing the low sun"}},{id:"state-5",practiceCount:3,correct:1,photo:{id:"1534330207526-8e81f10ec6fc",alt:"A man standing quietly in front of a bright window"}},{id:"state-6",practiceCount:3,correct:1,photo:{id:"1552838671-0e948f9f69b5",alt:"A woman sitting on green grass looking toward the morning sun"}},{id:"state-7",practiceCount:3,correct:0,photo:{id:"1633210155534-e43f00c1d627",alt:"A woman sitting on top of a rock outdoors, writing in a notebook"}}];function y(e,t){const o=g[t],s=e.judgment.primary.options.find(i=>i.id===e.judgment.primary.bestOptionId),r=e.judgment.primary.options.filter(i=>i.id!==s.id).map(i=>i.text);return r.splice(o.correct,0,s.text),{id:o.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,practice:[e.move.instructions[0],e.move.suggested.action,"Record the actual outcome and choose the next appropriate attempt."].slice(0,o.practiceCount),reflection:e.direction.reason.label,question:`${e.judgment.primary.scenario} ${e.judgment.primary.question}`,options:r,correct:o.correct,feedback:s.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,photo:o.photo}}const w={id:"state",title:"Still wound up? Give your next move room",subtitle:"7 lessons. Test one useful response, with optional tools for the moment before it.",description:"Carry one real transition through comfortable preparation, accurate interpretation, action, and review. Keep what serves your life without requiring a better mood.",scope:"For adults who want everyday tools to shift mood and energy. This is education, not diagnosis or treatment, and it is not a treatment for anxiety disorders, panic disorder or depression; it does not replace therapy or medication. Stop any breathing drill at once if you feel dizzy, light-headed, tingly or short of breath, return to normal breathing and sit down; if you have a heart or lung condition or are pregnant, check with a clinician before trying energizing breathwork, and never practice it while driving or in water. If you are in crisis or have thoughts of harming yourself, contact your local emergency number (911 in the US, 112 in Türkiye and much of Europe).",outcome:"One useful response at a recurring transition, honest attempt records, and a next-week plan that fits your capacity.",photo:{id:"1500080628126-901233e80205",alt:"A woman standing on a wooden dock at golden hour, raising one hand toward the light"},lessons:[d,l,h,u,p,m,f].map(y)};export{w as COURSE,v as SOURCES,d as STATE_1_V2,l as STATE_2_V2,h as STATE_3_V2,u as STATE_4_V2,p as STATE_5_V2,m as STATE_6_V2,f as STATE_7_V2};
